from pathlib import Path
import fcntl,hashlib,json,random,statistics,subprocess
p=Path(__file__).resolve().parent;variants=['baseline','control','isolated'];records={};build=[]
for cc,compiler in [('gcc','g++'),('clang','clang++')]:
 for skip in [False,True]:
  for v in variants:
   exe=p/f'{cc}_{skip}_{v}';cmd=['taskset','-c','8',compiler,'-std=c++23','-O2','-DHEADER="'+str(p/f'{v}.hpp')+'"',str(p/'bench.cpp'),'-o',str(exe)]
   if cc=='clang':cmd.insert(4,'--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15')
   if skip:cmd.insert(4,'-DSKIP_RUNTIME_CHECKS')
   subprocess.run(cmd,check=True,capture_output=True);build.append({'command':cmd,'binary_sha256':hashlib.sha256(exe.read_bytes()).hexdigest()})
  with open('/tmp/sirkit_four_hours_20261022/benchmark_graph.lock','w') as lock:
   fcntl.flock(lock,fcntl.LOCK_EX)
   for kind,n,reps in [(0,32,10000),(0,200000,100),(1,200000,10),(2,5000,100),(3,32,3000),(4,200000,100),(5,200000,10),(6,2000,30),(7,2000,2)]:
    vals={v:[] for v in variants};checks=set();rng=random.Random(kind+n)
    for rep in range(7):
     seq=variants[:];rng.shuffle(seq)
     for v in seq:
      out=subprocess.check_output(['taskset','-c','20',str(p/f'{cc}_{skip}_{v}'),str(kind),str(n),str(reps)],text=True).split();vals[v].append(float(out[0]));checks.add(out[1])
    assert len(checks)==1,(kind,n,checks)
    med={v:statistics.median(x) for v,x in vals.items()};ratio={v:med[v]/med['baseline'] for v in variants};records[f'{cc}/{skip}/{kind}/{n}']={'raw_ms':vals,'median_ms':med,'ratio':ratio,'checksum':checks.pop(),'repeated_calls':reps};print(cc,skip,kind,n,{v:round(x,3) for v,x in ratio.items()},flush=True)
(p/'body.json').write_text(json.dumps({'records':records,'build':build},indent=2)+'\n')

